/** @type {RichEditorExtension} */
const extension = {
  nodeSpec: {
    details: {
      attrs: { open: { default: true } },
      content: "summary block+",
      group: "block",
      selectable: true,
      defining: true,
      isolating: true,
      parseDOM: [{ tag: "details" }],
      toDOM: (node) => ["details", { open: node.attrs.open || undefined }, 0],
    },
    summary: {
      content: "inline*",
      parseDOM: [{ tag: "summary" }],
      toDOM: () => ["summary", 0],
    },
  },
  parse: {
    bbcode_open(state, token) {
      if (token.tag === "details") {
        state.openNode(state.schema.nodes.details);
        return true;
      }

      if (token.tag === "summary") {
        state.openNode(state.schema.nodes.summary);
        return true;
      }
    },
    bbcode_close(state, token) {
      if (token.tag === "details" || token.tag === "summary") {
        state.closeNode();
        return true;
      }
    },
  },
  serializeNode: {
    details(state, node) {
      state.renderContent(node);
      state.write("[/details]\n\n");
    },
    summary(state, node) {
      let hasSummary = false;
      // If the [details] tag has no summary.
      if (node.content.childCount === 0) {
        state.write("[details");
      } else {
        hasSummary = true;
        state.write('[details="');
        node.content.forEach(
          (child) =>
            child.text &&
            state.text(child.text.replace(/"/g, "“"), state.inAutolink)
        );
      }
      let finalState = "]\n";
      if (hasSummary) {
        finalState = `"${finalState}`;
      }
      state.write(finalState);
    },
  },
  plugins: {
    props: {
      handleClickOn(view, pos, node, nodePos) {
        // if the click position in the document is not the first within the summary node
        if (pos > nodePos + 1 || node.type.name !== "summary") {
          return false;
        }

        const details = view.state.doc.nodeAt(nodePos - 1);
        view.dispatch(
          view.state.tr.setNodeMarkup(nodePos - 1, null, {
            open: !details.attrs.open,
          })
        );
        return true;
      },
    },
  },
};

export default extension;
import { withPluginApi } from "discourse/lib/plugin-api";
import { i18n } from "discourse-i18n";
import richEditorExtension from "../lib/rich-editor-extension.js";

function initializeDetails(api) {
  api.addComposerToolbarPopupMenuOption({
    action: function (toolbarEvent) {
      toolbarEvent.applySurround(
        "\n" + `[details="${i18n("composer.details_title")}"]` + "\n",
        "\n[/details]\n",
        "details_text",
        { multiline: false }
      );
    },
    icon: "angle-right",
    label: "details.title",
    name: "details",
    shortcut: "Shift+D",
  });

  api.registerRichEditorExtension(richEditorExtension);
}

export default {
  name: "apply-details",

  initialize() {
    withPluginApi(initializeDetails);
  },
};
const rule = {
  tag: "details",
  before(state, tagInfo) {
    const attrs = tagInfo.attrs;
    const details = state.push("bbcode_open", "details", 1);
    state.push("bbcode_open", "summary", 1);

    if (attrs.open === "") {
      details.attrs = [["open", ""]];
    }

    let token = state.push("text", "", 0);
    token.content = attrs["_default"] || "";

    state.push("bbcode_close", "summary", -1);
  },

  after(state) {
    state.push("bbcode_close", "details", -1);
  },
};

export function setup(helper) {
  helper.allowList([
    "summary",
    "summary[title]",
    "details",
    "details[open]",
    "details.elided",
  ]);

  helper.registerPlugin((md) => {
    md.block.bbcode.ruler.push("details", rule);
  });
}
import * as Mod1 from "./initializers/apply-details";
import * as Mod2 from "./lib/discourse-markdown/details";
import * as Mod3 from "./lib/rich-editor-extension";
const compatModules = {
  "initializers/apply-details": Mod1,
  "lib/discourse-markdown/details": Mod2,
  "lib/rich-editor-extension": Mod3,
};
export { compatModules };
export default compatModules;
